R3.push(
  ['palacinke-klasik', 'Klasične palačinke', '🥞', 'du', 'dorucak', 30, 4, 380, 11, 'Brašno T-400:200 g|Mleko:0.4 l|Jaja:2 kom|Kisela voda:0.1 l|Suncokretovo ulje:30 ml|Džem:1 kom', 'Umuti jaja sa prstohvatom soli, dodaj mleko.|Postepeno umešaj brašno žicom dok ne nestanu grudvice.|Dodaj kiselu vodu i ulje; testo odmori 15 min.|Tiganj zagrej i premaži tankim slojem ulja.|Sipaj kutlaču testa, zarotiraj tiganj da se razlije, peci 1 min, okreni i peci još 30 s.|Fil po izboru: džem, eurokrem, orasi sa šećerom.|💡 Prva palačinka uvek „ne uspe“ – tiganj je tek onda pravilno zagrejan.'],
  ['americke-palacinke', 'Američke palačinke sa medom', '🥞', 'd', 'dorucak', 25, 3, 420, 12, 'Brašno T-400:200 g|Mleko:0.25 l|Jaja:1 kom|Puter:1 kom:30 g|Prašak za pecivo:1 pak|Šećer:20 g|Med:40 g|Borovnice:1 pak', 'Pomešaj brašno, prašak, šećer i prstohvat soli.|U drugoj posudi umuti jaje, mleko i otopljen puter.|Sjedini mešavine kratko – grudvice su u redu.|Na blago nauljen tiganj sipaj po 3 kašike testa i peci dok se na vrhu ne pojave mehurići (2 min), okreni i peci još 1 min.|Posluži sa medom i borovnicama.|💡 Ne mešaj testo predugo – tako palačinke ostanu debele i pufnaste.'],
  ['ajvar-jaja', 'Jaja na oko sa slaninom i tostom', '🍳', 'd', 'dorucak', 15, 2, 480, 22, 'Jaja:4 kom|Slanina:100 g|Tost hleb:0.25 kom:4 kriške|Paradajz:1 kom', 'Slaninu prži na suvom tiganju 4–5 min dok ne postane hrskava, izvadi.|U istoj masnoći na tihoj vatri ispeci jaja 3–4 min.|Hleb tostiraj.|Posluži sa slaninom i paradajzom.|💡 Na tihoj vatri belance ostaje mekano, bez zagorelih ivica.'],
  ['jaja-benedikt', 'Poširana jaja na tostu sa šunkom', '🥚', 'd', 'dorucak', 25, 2, 460, 26, 'Jaja:4 kom|Šunka:100 g|Tost hleb:0.25 kom:4 kriške|Puter:1 kom:30 g|Sirće::1 kašika|Limun:0.5 kom', 'U šerpi zagrej vodu sa sirćetom da samo „treperi“.|Razbij jaje u šoljicu, napravi vir u vodi i pusti jaje u sredinu.|Kuvaj 3–4 min (ili 5 min da se žumance stegne), izvadi rešetkastom kašikom.|Hleb tostiraj, premaži puterom i stavi šunku.|Preko stavi jaje, pokapaj otopljenim puterom sa limunom i pobiberi.|💡 Sveža jaja se najlepše poširaju – belance ostaje na okupu.'],
  ['francuski-omlet-sir', 'Omlet sa pečurkama i sirom', '🍳', 'dv', 'dorucak', 15, 1, 420, 26, 'Jaja:3 kom|Šampinjoni:0.5 pak|Kačkavalj:40 g|Puter:1 kom:15 g', 'Pečurke iseci na listiće i proprži na puteru 4 min, izvadi.|Jaja umuti sa solju.|Sipaj ih u tiganj sa ostatkom putera na srednjoj vatri i pomeraj ivice ka sredini.|Kad je skoro stegnut, stavi pečurke i sir na jednu polovinu.|Preklopi i skini sa vatre.|💡 Francuski omlet je mekan iznutra – ne peci ga do kraja na vatri.'],
);

